	root := make([]int, n+1)
	for i := range root {
		root[i] = i
	}
	find := func(x int) int {
		for root[x] != x {
			root[x] = root[root[x]]
			x = root[x]
		}
		return x
	}
	for _, e := range edges {
		u, v := e[0], e[1]
		if cand2 != nil && u == cand2[0] && v == cand2[1] {
			continue // try the tree without the later candidate
		}
		ru, rv := find(u), find(v)
		if ru == rv { // a cycle even so
			if cand1 != nil {
				return cand1
			}
			return []int{u, v}
		}
		root[rv] = ru
	}
	return cand2
